Appendix
Single tau
functions {
  real vasicek_quantile_lpdf(vector y, real theta, vector mu, real tau) {
    int N = num_elements(y);
    real lpdf = 0.5 * N * (log1m(theta) - log(theta));
    vector[N] qnorm_mu = inv_Phi(mu);
    real qnorm_tau = inv_Phi(tau);
    vector[N] qnorm_y = inv_Phi(y);
    vector[N] qnorm_alpha = -sqrt(theta) * qnorm_tau + 
                              qnorm_mu * sqrt(1 - theta);

    return lpdf + 0.5 * dot_self(qnorm_y) - 
            0.5 * sum( (sqrt(1 - theta) * qnorm_y - qnorm_alpha)^2 / theta);
  }
}
data {
  int&lt;lower=0&gt; N;
  vector[N] y;
  vector[N] x;
  real&lt;lower=0, upper=1&gt; tau;
} 
parameters {
  real alpha;
  real beta;
  real sigma;
} 
model {
  alpha ~ normal(0, 4);
  beta ~ normal(0, 4);
  sigma ~ normal(0, 2);
  y ~ vasicek_quantile(inv_logit(sigma), inv_logit(alpha + beta * x), tau);
}
Multiple tau
functions {
  real vasicek_quantile_lpdf(vector y, real theta, vector mu, real tau) {
    if (tau &lt;= 0 || tau &gt;= 1) 
      reject("tau must be between 0 and 1 found tau = ", tau);

    if (theta &lt;= 0 || theta &gt;= 1) 
      reject("theta must be between 0 and 1 found theta = ", theta);

    int N = num_elements(y);
    real lpdf = 0.5 * N * (log1m(theta) - log(theta));
    vector[N] qnorm_mu = inv_Phi(mu);
    real qnorm_tau = inv_Phi(tau);
    vector[N] qnorm_y = inv_Phi(y);
    vector[N] qnorm_alpha = -sqrt(theta) * qnorm_tau +  
                              qnorm_mu * sqrt(1 - theta);

    return lpdf + 
            0.5 * dot_self(qnorm_y) - 
            0.5 * sum( (sqrt(1 - theta) * qnorm_y - qnorm_alpha)^2 / theta);
  }
}
data {
  int&lt;lower=0&gt; N;
  vector[N] y;
  vector[N] x;

  int&lt;lower=1&gt; K;
  vector&lt;lower=0, upper=1&gt;[K] tau;
} 
parameters {
  vector[K] alpha;
  vector[K] beta;
  vector[K] sigma;
} 
model {
  alpha ~ normal(0, 4);
  beta ~ normal(0, 4);
  sigma ~ normal(0, 2);

  for (i in 1:K)
    y ~ vasicek_quantile(inv_logit(sigma[i]), 
                         inv_logit(alpha[i] + beta[i] * x), tau[i]);
}

Quantile regressions are relatively new in the Bayesian literature first appearing in Yu and Moyeed (2001) who described an asymmetric Laplace distribution to estimate the conditional quantiles. This post is going to show the asymmetric Laplace and the augmented version. In part II I will show the score likelihood method.
The asymmetric Laplace distribution is given as
\[
\operatorname{ALD}(Y \mid x, \beta) = \frac{\tau^n (1 - \tau)^n}{\sigma^n}\exp \bigg( -\frac{\sum_{i=1}^n \rho_\tau (y_i - x_i^{\top}\beta)}{\sigma} \bigg)
\]
where
\[
\rho_\tau(u) = \frac{|u| + (2\tau - 1)u}{2}
\]
We may write this in Stan as
Show the code
functions{
real q_loss(real q, vector u){
  return 0.5 * sum(abs(u) + (2 * q - 1) * u);
}

real ald_lpdf(vector y, real q, real sigma, vector q_est){
  int N = num_elements(y);

  return N * (log(q) + log1m(q) - log(sigma)) - q_loss(q, y - q_est) / sigma;
}
}
data {
  int N;                   // Number of observation
  int P;                   // Number of predictors
  real&lt;lower=0, upper=1&gt; q;
  vector[N] y;             // Response variable sorted
  matrix[N, P] x;
}
parameters {
  vector[P] beta;
  real&lt;lower=0&gt; sigma;
}
model {
  beta ~ normal(0, 4);
  sigma ~ exponential(1);
  y ~ ald(q, sigma, x * beta);
}
