5. Stan Implementation
Copy this block directly into your Stan program.
functions {
  /**
   * Maps unconstrained R^(K-1) vector x to Unit Vector S^(K-1).
   *
   * @param x Unconstrained vector of length K-1
   * @param K Dimension of the embedding space (output vector size)
   * @return Unit vector of length K
   */
  vector hyper_tanh_to_unit_jacobian(vector x, int K) {
    vector[K] y;
    real r = 1.0;

    for (i in 1:K - 2) {
      real val = x[i];
      y[i] = r * tanh(val);
      real cosh_val = cosh(val);
      r = r * inv(cosh_val);
      real power = K - i; 
      jacobian += -power * log(cosh_val);
    }

    real last_x = x[K-1];
    jacobian += log(2.0) - log1p(square(last_x));

    real denom = 1.0 + square(last_x);

    y[K-1] = r * (1.0 - square(last_x)) / denom;
    y[K] = r * (2.0 * last_x) / denom;

    return y;
  }
}

data {
  int&lt;lower=2&gt; K;
}

parameters {
  vector[K - 1] x_raw; // Unconstrained
}

transformed parameters {
  vector[K] mu = hyper_tanh_to_unit_jacobian(x_raw, K);
}

model {
  // uniform on the sphere
}

Score function
The following Stan model implements the single \(\tau\) code. I’ll simulate some data and compare to the asymmetric Laplace:


Show the code
functions{
  vector q_loss(real q, vector u){
    return 0.5 * (abs(u) + (2 * q - 1) * u);
  }

  vector score(real q, vector y, matrix x, vector beta) {
    return transpose(x) * q_loss(q, y - x * beta );
  }

  matrix make_w (matrix x, real q) {
    int N = rows(x);
    int P = cols(x);
    real alpha = 1 / (q * (1 - q));
    matrix[P, P] x_out = inverse_spd(crossprod(x));

    return alpha * x_out * N;
  }
}
data {
  int N;                 // Number of observation
  int P;                 // Number of predictors
  real q;
  vector[N] y;           // Response variable sorted
  matrix[N, P] x;
}
transformed data {
  matrix[P, P] W = make_w(x, q);
}
parameters {
  vector[P] beta;
}
model {
  vector[P] score_vec = score(q, y, x, beta);

  beta ~ normal(0, 4);

  target += -quad_form(W, score_vec) / (2 * N);
}


